mapper.select:
SELECT /* getNoticeCategoryCnt */
       COUNT(1)
  FROM TB_CODEXD
 WHERE COMM_CODE = #{cateCgrp}
   AND COMD_CODE = #{cateCode}
   AND USEE_YSNO = #{useeYsno}

mapper.insert:
INSERT /* setNotice */
  INTO CT_NOTICE (
       NOTI_NUMB
     , VERS_NUMB
     , CATE_CGRP
     , CATE_CODE
     , NOTI_TITL
     , NOTI_ENTL
     , NOTI_CNTN
     , NOTI_ENCT
     , TOPX_YSNO
     , DPLY_YSNO
     , REGI_ADMN
     , REGI_DATE
     , UPDT_ADMN
     , UPDT_DATE
) VALUES (
       #{notiNumb,jdbcType=BIGINT}
     , #{versNumb}
     , #{cateCgrp}
     , #{cateCode}
     , #{notiTitl}
     , #{notiEntl}
     , #{notiCntn}
     , #{notiEnct}
     , #{topxYsno}
     , #{dplyYsno}
     , #{regiAdmn}
     , COALESCE(#{regiDate,jdbcType=TIMESTAMP}, CURRENT_TIMESTAMP)
     , #{updtAdmn,jdbcType=BIGINT}
     , CASE WHEN #{updtAdmn,jdbcType=BIGINT} IS NULL THEN NULL ELSE CURRENT_TIMESTAMP END
)

mapper.update:
UPDATE /* uptNotice */
       CT_NOTICE
   SET CATE_CGRP = #{cateCgrp}
     , CATE_CODE = #{cateCode}
     , NOTI_TITL = #{notiTitl}
     , NOTI_ENTL = #{notiEntl}
     , NOTI_CNTN = #{notiCntn}
     , NOTI_ENCT = #{notiEnct}
     , TOPX_YSNO = #{topxYsno}
     , UPDT_ADMN = #{updtAdmn}
     , UPDT_DATE = CURRENT_TIMESTAMP
 WHERE NOTI_NUMB = #{notiNumb}
   AND VERS_NUMB = #{versNumb}
   AND DPLY_YSNO = #{dplyYsno}

UPDATE /* uptNoticeDeployOff */
       CT_NOTICE
   SET DPLY_YSNO = #{no}
 WHERE NOTI_NUMB = #{notiNumb}
   AND DPLY_YSNO = #{yes}

UPDATE /* uptNoticeDeployOn */
       CT_NOTICE
   SET DPLY_YSNO = #{yes}
     , DPLY_DATE = CURRENT_TIMESTAMP
     , DPLY_ADMN = #{dplyAdmn}
 WHERE NOTI_NUMB = #{notiNumb}
   AND VERS_NUMB = #{versNumb}

mapper.delete:
DELETE /* delNoticeView */
  FROM TB_USVIEW
 WHERE VIEW_TYPE = #{viewType}
   AND TAGT_NUMB = #{tagtNumb}

DELETE /* delNotice */
  FROM CT_NOTICE
 WHERE NOTI_NUMB = #{notiNumb}
